#include "presentation.hpp"
#import <AppKit/AppKit.h>
#include <filesystem>
#include <fstream>
#include <stdexcept>
#include <vector>
static void require(bool value,const std::string &why){if(!value)throw std::runtime_error(why);}
static void image(const std::string &file,unsigned value){auto png=[[NSBitmapImageRep alloc]initWithData:[NSData dataWithContentsOfFile:@(file.c_str())]];require(png&&png.pixelsWide==64&&png.pixelsHigh==48,"Incorrect capture extent");const auto pixel=png.bitmapData+(png.bitmapFormat&NSAlphaFirstBitmapFormat?1:0);require(std::abs(int(pixel[0])-int(value))<=1,"Incorrect captured source/final colour");}
int main(int argc,char **argv){@autoreleasepool{try{
    require(argc==3,"Usage: effects-presenter-capture OUTPUT INCLUDE_DIRECTORY");const std::string root=argv[1],plan=root+"/plan.json",fx=root+"/effect.fx",capture=root+"/frame",trigger=root+"/request";std::filesystem::create_directories(root);setenv("RESHADE_EFFECT_PLAN",plan.c_str(),1);setenv("RESHADE_INCLUDE_PATH",argv[2],1);setenv("RESHADE_CAPTURE_PREFIX",capture.c_str(),1);setenv("RESHADE_CAPTURE_TRIGGER",trigger.c_str(),1);
    std::ofstream(fx)<<"#include \"ReShade.fxh\"\nfloat4 Filter(float4 p:SV_Position,float2 uv:TEXCOORD):SV_Target{float4 c=tex2D(ReShade::BackBuffer,uv);return float4((c.rgb+.2)*.5,c.a);}\ntechnique Main{pass{VertexShader=PostProcessVS;PixelShader=Filter;}}\n";
    NSDictionary *doc=@{@"schema":@1,@"mode":@"advanced",@"revision":[@"" stringByPaddingToLength:64 withString:@"a" startingAtIndex:0],@"nodes":@[@{@"id":@"shader",@"kind":@"shader",@"format":@"fx",@"file":@(fx.c_str()),@"key":[@"" stringByPaddingToLength:64 withString:@"b" startingAtIndex:0],@"revision":[@"" stringByPaddingToLength:64 withString:@"c" startingAtIndex:0],@"enabled":@YES}]};require([[NSJSONSerialization dataWithJSONObject:doc options:0 error:nil]writeToFile:@(plan.c_str()) atomically:YES],"Cannot write capture plan");
    auto device=MTLCreateSystemDefaultDevice();require(device!=nil,"Metal unavailable");auto queue=[device newCommandQueue];auto layer=[CAMetalLayer layer];layer.device=device;layer.pixelFormat=MTLPixelFormatBGRA8Unorm;layer.drawableSize=CGSizeMake(64,48);auto descriptor=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm width:64 height:48 mipmapped:NO];descriptor.storageMode=MTLStorageModeShared;descriptor.usage=MTLTextureUsageShaderRead|MTLTextureUsageShaderWrite|MTLTextureUsageRenderTarget;auto source=[device newTextureWithDescriptor:descriptor];std::vector<unsigned char> bytes(64*48*4,64);for(size_t i=3;i<bytes.size();i+=4)bytes[i]=255;[source replaceRegion:MTLRegionMake2D(0,0,64,48) mipmapLevel:0 withBytes:bytes.data() bytesPerRow:64*4];int owner=0;macfx::FramePresenter presenter(layer,&owner);
    std::ofstream(trigger)<<"capture";auto commands=[queue commandBuffer];auto result=presenter.submit(commands,source,1,CACurrentMediaTime());require(result.encoded,result.reason);require(!std::filesystem::exists(trigger),"Presenter did not admit the capture trigger");require(!std::filesystem::exists(capture+"-before.png")&&!std::filesystem::exists(capture+"-after.png"),"Capture was written before GPU completion");auto done=dispatch_semaphore_create(0);[commands addCompletedHandler:^(id<MTLCommandBuffer>){dispatch_semaphore_signal(done);}];[commands commit];require(!dispatch_semaphore_wait(done,dispatch_time(DISPATCH_TIME_NOW,10*NSEC_PER_SEC)),"Capture GPU deadline");for(unsigned i=0;i<100&&!std::filesystem::exists(capture+"-after.png");++i)[NSThread sleepForTimeInterval:.02];image(capture+"-before.png",64);image(capture+"-after.png",58);
    const std::string cancelled=root+"/cancelled";setenv("RESHADE_CAPTURE_PREFIX",cancelled.c_str(),1);std::ofstream(trigger)<<"capture";@autoreleasepool{auto abandoned=[queue commandBuffer];auto next=presenter.submit(abandoned,source,2,CACurrentMediaTime());require(next.encoded,next.reason);require(!std::filesystem::exists(trigger),"Cancelled frame did not own its capture request");}presenter.stop();require(!std::filesystem::exists(cancelled+"-before.png")&&!std::filesystem::exists(cancelled+"-after.png"),"Unsubmitted frame published a capture pair");
    std::printf("FramePresenter capture: trigger admitted; source64/final58 actual PNGs after GPU completion; cancelled unsubmitted frame writes neither image\n");return 0;
}catch(const std::exception &error){std::fprintf(stderr,"%s\n",error.what());return 1;}}}
